
<template>
    
    <!-- Бегущая лента в углу -->
    <div class="corner-marquee">
        <div class="corner-marquee__track">

            <!-- Первый набор (смешанный) -->
            <div class="corner-marquee__item" v-for="customer in ad" :key="customer.name"><img :src="customer.content" :alt="customer.name"></div>

            <!-- Точный дубликат для бесшовности -->
            <div class="corner-marquee__item" v-for="customer in ad" :key="customer.name"><img :src="customer.content" :alt="customer.name"></div>

        </div>
    </div>


</template>

<script lang="ts">
    import { defineComponent } from 'vue';

    export default defineComponent({
        data(): Data {
            return {
                loading: false,
                post: null,
                isloginshow: true,
                userLoginInput: null,
                userPasswordInput: null,
                issessionexpired: true,
                loginMessage: null,
                loadercolor: "#ffff00",
                ad: [
                    { name: "mark", content: "data:image/jpeg;base64," },
                    { name: "elisabet", content: "data:image/jpeg;base64," },
                    { name: "brad", content: "data:image/webp;base64," },
                    { name: "brad", content: "data:image/webp;base64," },
                    { name: "brad", content: "data:image/webp;base64," },
                    { name: "brad", content: "data:image/webp;base64," },
                    { name: "brad", content: "data:image/webp;base64," },
                    { name: "brad", content: "data:image/webp;base64," },
                    ],
            };
        },
        created() {
            // fetch the data when the view is created and the data is
            // already being observed
            //this.requestloadercolor();
            /*this.userLogin();*/
            this.userLoginInput = this.$cookies.set("steadyforumuname");
        },
        watch: {
            // call again the method if the route changes
        },
        methods: {
            async sha256(message) {
                const msgBuffer = new TextEncoder('utf-8').encode(message);
                const hashBuffer = await crypto.subtle.digest('SHA-256', msgBuffer);
                const hashArray = Array.from(new Uint8Array(hashBuffer));
                const hashHex = hashArray.map(b => ('00' + b.toString(16)).slice(-2)).join('');
                return hashHex;
            },
            async userLogin() {  
                this.$router.push({ name: 'slider' });
                if (this.$cookies.get("steadyforumsessionid")) {
                    fetch('/api/Details/' + this.$cookies.get("steadyforumsessionid"))
                        .then(response => {
                            if (response.status == 400) {
                                this.isloginshow = true;
                            } else if (response.status == 200) {
                                this.isloginshow = false;
                            }
                            return;
                    })
                }

                if (!this.userLoginInput) { return }

                var userCredBase64 = btoa(unescape(encodeURIComponent(this.userLoginInput + this.userPasswordInput)));
                var userCredSha256 = await this.sha256(userCredBase64)


                fetch('/api/Login/' + this.userLoginInput + "/" + userCredSha256)
                    .then(r => r.json())
                    .then(json => {
                        this.$cookies.remove('steadyforumuname');
                        this.$cookies.set("steadyforumuname", this.userLoginInput, "expiring time");
                        this.$cookies.remove('steadyforumsessionid');
                        this.$cookies.set("steadyforumsessionid", json.sessionid, "expiring time")
                        this.$router.push({ name: 'slider' });  /*instead this.isloginshow = false;*/                        
                        return;
                    });
            },
            requestloadercolor() {
                fetch('/api/LoginColor/' + this.sessionId)
                    .then(r => r.json())
                    .then(json => {
                        this.loadercolor = json.loadercolor;
                        return;
                    });
            },
            searchPost() {

            }
        },
    });
</script>

