        top: 140px; /* Смещение от верха */
        right: -80px; /* Смещение вправо (чтобы компенсировать поворот) */
        width: 400px; /* Длина видимой области ленты */
        overflow: hidden;
        background: #ff57221c; /* Яркий цвет ленты (можно изменить) */
        padding: 10px 0;
        box-shadow: 0 4px 10px rgba(0,0,0,0.3);
        z-index: 9999; /* Поверх всех элементов на сайте */
        /* Поворачиваем ленту на 45 градусов */
        transform: rotate(45deg);
        transform-origin: right top;
    }

    /* Линия с контентом */
    .corner-marquee__track {
        display: flex;
        gap: 30px;
