    }

    /* Универсальный элемент (цифра или картинка) */
    .corner-marquee__item {
        flex-shrink: 0;
        display: flex;
        align-items: center;
        justify-content: center;
        /* Стили для текста/цифр */
        font-size: 28px;
        font-weight: bold;
