        font-family: sans-serif;
        min-width: 40px;
    }

        /* Стили для картинок, если они есть */
        .corner-marquee__item img {
            height: 55px; /* Картинки автоматически уменьшатся под размер ленты */
            width: auto;
            display: block;
            object-fit: contain;
        }

    /* Анимация цикличного движения на 50% длины */
